#include <bits/stdc++.h>using namespace std;using ll = long long; struct Node{         ll sum, mx;}; class SegTree{         int n;         vector<Node> seg; public:         SegTree(int n) : n(n)         {                  seg.resize(4 * n);         }          Node merge(Node a, Node b)         {                  return {a.sum + b.sum, max(a.mx, b.mx)};         }          void build(int idx, int l, int r, vector<ll> &a)         {                  if (l == r)                  {                           seg[idx] = {a[l], a[l]};                           return;                  }                  int mid = (l + r) >> 1;                  build(2 * idx + 1, l, mid, a);                  build(2 * idx + 2, mid + 1, r, a);                  seg[idx] = merge(seg[2 * idx + 1], seg[2 * idx + 2]);         }          // Point update: a[pos] = val         void updateSet(int idx, int l, int r, int pos, ll val)         {                  if (l == r)                  {                           seg[idx] = {val, val};                           return;                  }                  int mid = (l + r) >> 1;                  if (pos <= mid)                           updateSet(2 * idx + 1, l, mid, pos, val);                  else                           updateSet(2 * idx + 2, mid + 1, r, pos, val);                  seg[idx] = merge(seg[2 * idx + 1], seg[2 * idx + 2]);         }          // Range modulo         void updateMod(int idx, int l, int r, int ql, int qr, ll x)         {                  if (r < ql || l > qr || seg[idx].mx < x)                           return;                   if (l == r)                  {                           seg[idx].sum %= x;                           seg[idx].mx = seg[idx].sum;                           return;                  }                   int mid = (l + r) >> 1;                  updateMod(2 * idx + 1, l, mid, ql, qr, x);                  updateMod(2 * idx + 2, mid + 1, r, ql, qr, x);                  seg[idx] = merge(seg[2 * idx + 1], seg[2 * idx + 2]);         }          // Range sum query         ll querySum(int idx, int l, int r, int ql, int qr)         {                  if (r < ql || l > qr)                           return 0;                  if (l >= ql && r <= qr)                           return seg[idx].sum;                  int mid = (l + r) >> 1;                  return querySum(2 * idx + 1, l, mid, ql, qr) +                         querySum(2 * idx + 2, mid + 1, r, ql, qr);         }}; int main(){         ios::sync_with_stdio(false);         cin.tie(nullptr);          int n, m;         cin >> n >> m;          vector<ll> a(n);         for (int i = 0; i < n; i++)                  cin >> a[i];          SegTree st(n);         st.build(0, 0, n - 1, a);          while (m--)         {                  int type;                  cin >> type;                  if (type == 1)                  {                           int l, r;                           cin >> l >> r;                           cout << st.querySum(0, 0, n - 1, l - 1, r - 1) << "\n";                  }                  else if (type == 2)                  {                           int l, r;                           ll x;                           cin >> l >> r >> x;                           st.updateMod(0, 0, n - 1, l - 1, r - 1, x);                  }                  else                  {                           int k;                           ll x;                           cin >> k >> x;                           st.updateSet(0, 0, n - 1, k - 1, x);                  }         }         return 0;}